// Deterministic test identities -- fixed, obviously-fake UUIDs (not
// gen_random_uuid()) for every fixture row, not just the people, so any
// test file can reference them as plain constants without depending on a
// setup function's return value crossing Vitest's globalSetup/test-file
// process boundary. All in the 00000000-0000-4000-8000-0000000000xx
// range, never generated by any real signup/app-write path, so nothing
// here could ever collide with real data.
import { randomUUID } from "node:crypto";
import { withCommittedServiceRole } from "./db-client";

export const IDS = {
  coachA: "00000000-0000-4000-8000-0000000000a1",
  coachB: "00000000-0000-4000-8000-0000000000b1",
  athleteA: "00000000-0000-4000-8000-0000000000a2",
  athleteB: "00000000-0000-4000-8000-0000000000b2",
  athleteC: "00000000-0000-4000-8000-0000000000c1",

  coachAthleteRelAA: "00000000-0000-4000-8000-0000000010a1",
  coachAthleteRelBB: "00000000-0000-4000-8000-0000000010b1",

  templateA: "00000000-0000-4000-8000-0000000020a1",

  scheduledWorkoutA: "00000000-0000-4000-8000-0000000030a1", // Coach A -> Athlete A, published
  scheduledWorkoutB: "00000000-0000-4000-8000-0000000030b1", // Coach B -> Athlete B, published
  scheduledWorkoutADraft: "00000000-0000-4000-8000-0000000030a2", // Coach A -> Athlete A, unpublished

  completedWorkoutA: "00000000-0000-4000-8000-0000000040a1", // Athlete A's completion of scheduledWorkoutA
  completedWorkoutB: "00000000-0000-4000-8000-0000000040b1", // Athlete B's completion of scheduledWorkoutB

  messageAA: "00000000-0000-4000-8000-0000000050a1", // in the Coach A <-> Athlete A thread, sent by Coach A
  messageBB: "00000000-0000-4000-8000-0000000050b1", // in the Coach B <-> Athlete B thread, sent by Coach B
  messageFromAthleteA: "00000000-0000-4000-8000-0000000050a3", // in the Coach A <-> Athlete A thread, sent by Athlete A

  commentOnA: "00000000-0000-4000-8000-0000000060a1", // a comment on scheduledWorkoutA
} as const;

async function createProfile(client: import("pg").PoolClient, id: string, name: string) {
  await client.query("insert into auth.users (id, email) values ($1, $2) on conflict (id) do nothing", [
    id,
    `${name.toLowerCase().replace(/\s+/g, ".")}@rls-test.invalid`,
  ]);
  await client.query(
    "insert into public.profiles (id, display_name, timezone, units) values ($1, $2, 'UTC', 'mi') on conflict (id) do nothing",
    [id, name],
  );
}

/** Coach A -> Athlete A (active), Coach B -> Athlete B (active), Athlete C
 * unattached to anyone -- matching the required relationship matrix
 * exactly. Also grants both coaches the private_coach permission, and
 * creates one published workout per real relationship, one unpublished
 * draft, one workout template, and one completion -- the minimum realistic
 * data the adversarial matrix needs to exercise every table's policies. */
export async function setupFixtures(): Promise<void> {
  await withCommittedServiceRole(async (client) => {
    for (const [id, name] of [
      [IDS.coachA, "Test Coach A"],
      [IDS.coachB, "Test Coach B"],
      [IDS.athleteA, "Test Athlete A"],
      [IDS.athleteB, "Test Athlete B"],
      [IDS.athleteC, "Test Athlete C"],
    ] as const) {
      await createProfile(client, id, name);
    }

    for (const coachId of [IDS.coachA, IDS.coachB]) {
      await client.query(
        "insert into public.user_permissions (user_id, permission) values ($1, 'private_coach') on conflict do nothing",
        [coachId],
      );
    }

    await client.query(
      "insert into public.coach_athletes (id, coach_id, athlete_id, status) values ($1, $2, $3, 'active')",
      [IDS.coachAthleteRelAA, IDS.coachA, IDS.athleteA],
    );
    await client.query(
      "insert into public.coach_athletes (id, coach_id, athlete_id, status) values ($1, $2, $3, 'active')",
      [IDS.coachAthleteRelBB, IDS.coachB, IDS.athleteB],
    );

    await client.query(
      "insert into public.workout_templates (id, coach_id, name, workout_type) values ($1, $2, 'Test Template', 'easy')",
      [IDS.templateA, IDS.coachA],
    );

    await client.query(
      `insert into public.scheduled_workouts (id, athlete_id, coach_id, scheduled_date, title, published_at)
       values ($1, $2, $3, current_date, 'Easy Run', now())`,
      [IDS.scheduledWorkoutA, IDS.athleteA, IDS.coachA],
    );
    await client.query(
      `insert into public.scheduled_workouts (id, athlete_id, coach_id, scheduled_date, title, published_at)
       values ($1, $2, $3, current_date, 'Easy Run', now())`,
      [IDS.scheduledWorkoutB, IDS.athleteB, IDS.coachB],
    );
    await client.query(
      `insert into public.scheduled_workouts (id, athlete_id, coach_id, scheduled_date, title, published_at)
       values ($1, $2, $3, current_date, 'Draft Workout', null)`,
      [IDS.scheduledWorkoutADraft, IDS.athleteA, IDS.coachA],
    );

    await client.query(
      `insert into public.completed_workouts (id, scheduled_workout_id, athlete_id, actual_distance_m, rpe)
       values ($1, $2, $3, 8000, 5)`,
      [IDS.completedWorkoutA, IDS.scheduledWorkoutA, IDS.athleteA],
    );
    await client.query(
      `insert into public.completed_workouts (id, scheduled_workout_id, athlete_id, actual_distance_m, rpe)
       values ($1, $2, $3, 8000, 5)`,
      [IDS.completedWorkoutB, IDS.scheduledWorkoutB, IDS.athleteB],
    );

    await client.query(
      `insert into public.coach_athlete_messages (id, coach_athlete_id, sender_id, body)
       values ($1, $2, $3, 'Hello Athlete A, from Coach A')`,
      [IDS.messageAA, IDS.coachAthleteRelAA, IDS.coachA],
    );
    await client.query(
      `insert into public.coach_athlete_messages (id, coach_athlete_id, sender_id, body)
       values ($1, $2, $3, 'Hello Athlete B, from Coach B')`,
      [IDS.messageBB, IDS.coachAthleteRelBB, IDS.coachB],
    );
    await client.query(
      `insert into public.coach_athlete_messages (id, coach_athlete_id, sender_id, body)
       values ($1, $2, $3, 'Hello Coach A, from Athlete A')`,
      [IDS.messageFromAthleteA, IDS.coachAthleteRelAA, IDS.athleteA],
    );

    await client.query(
      `insert into public.workout_comments (id, scheduled_workout_id, author_id, body)
       values ($1, $2, $3, 'How did this feel?')`,
      [IDS.commentOnA, IDS.scheduledWorkoutA, IDS.coachA],
    );
  });
}

/** Deletes every fixture row, cascading -- safe to call even if setup
 * partially failed, and safe to call more than once. */
export async function teardownFixtures(): Promise<void> {
  await withCommittedServiceRole(async (client) => {
    const peopleIds = [IDS.coachA, IDS.coachB, IDS.athleteA, IDS.athleteB, IDS.athleteC];
    await client.query("delete from public.profiles where id = any($1)", [peopleIds]);
    await client.query("delete from auth.users where id = any($1)", [peopleIds]);
  });
}

/** A syntactically-valid but never-fixture-created uuid, for tests that
 * need "an id that definitely doesn't exist" rather than "an id belonging
 * to someone else." */
export function randomNonExistentId(): string {
  return randomUUID();
}
